SELECT id, interval_code, candle_open_time, generated_at, created_at, decision, original_decision, trend_score, confidence_score, confluence_status, confluence_entry_allowed, confluence_higher_interval, confluence_higher_decision, confluence_higher_trend_score, confluence_higher_signal_generated_at, final_entry_allowed, LEFT(confluence_explanation, 400) AS conf_expl_400 FROM crypto_ai.trade_signal WHERE symbol = 'ACEUSDT' AND ((interval_code IN ('5m','1h') AND generated_at BETWEEN '2026-10-12 07:55:00' AND '2026-10-12 10:06:00') OR id = 176710) ORDER BY generated_at LIMIT 60;